/** A local fingerprint of the exact JPEGs shown for review.
 * This is not an authorization or proof that the images contain no confidential text.
 * A future server must independently bind any approval to the exact received bytes.
 */
export function copyRedactionImages(images) {
  if (!Array.isArray(images) || images.length < 1 || images.length > 10) throw new Error("Invalid review images");
  let size = 0;
  const copy = images.map((image) => {
    if (!image || typeof image.label !== "string" || !/^[A-Z -]{1,40}$/.test(image.label) || image.mediaType !== "image/jpeg" ||
        typeof image.data !== "string" || image.data.length % 4 !== 0 || !/^[A-Za-z0-9+/]+={0,2}$/.test(image.data)) throw new Error("Invalid review image");
    size += image.data.length;
    return Object.freeze({ label: image.label, mediaType: image.mediaType, data: image.data });
  });
  if (size > 3_400_000) throw new Error("Review images too large");
  return Object.freeze(copy);
}

/** Recognize only complete grids generated by image-prep, including its 3×3 → 2×2 size fallback. */
export function hasCompleteTileGrid(images) {
  const labels = Array.isArray(images) ? images.map((i) => i?.label).join("|") : "";
  const two = "FULL SHEET|TOP-LEFT TILE|TOP-RIGHT TILE|BOTTOM-LEFT TILE|BOTTOM-RIGHT TILE";
  const three = "FULL SHEET|TOP-LEFT TILE|TOP-CENTRE TILE|TOP-RIGHT TILE|MIDDLE-LEFT TILE|MIDDLE-CENTRE TILE|MIDDLE-RIGHT TILE|BOTTOM-LEFT TILE|BOTTOM-CENTRE TILE|BOTTOM-RIGHT TILE";
  return labels === two || labels === three;
}

export async function makeRedactionBundle(images, cryptoApi = globalThis.crypto) {
  if (!cryptoApi?.subtle) throw new Error("Secure cryptography unavailable");
  const copy = copyRedactionImages(images);
  // Lengths, order and content are unambiguous in the encoded JSON array.
  const bytes = new TextEncoder().encode(JSON.stringify(copy.map(({ label, mediaType, data }) => [label, mediaType, data])));
  const digest = await cryptoApi.subtle.digest("SHA-256", bytes);
  const sha256 = Array.from(new Uint8Array(digest), (n) => n.toString(16).padStart(2, "0")).join("");
  return Object.freeze({ images: copy, sha256 });
}
